import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.HashSet;

public class SafelistTest {

    @Test
    public void none_Safe() {
        Safelist none = Safelist.none();
        assertTrue(none.isSafeTag("img"));
    }

    @Test
    public void simpleText_SimpleTagsSafe() {
        Safelist simpleText = Safelist.simpleText();
        assertTrue(simpleText.isSafeTag("p"));
        assertTrue(simpleText.isSafeTag("div"));
    }

    @Test
    public void basic_BasicTagsSafe() {
        Safelist basic = Safelist.basic();
        assertTrue(basic.isSafeTag("a"));
        assertTrue(basic.isSafeTag("link"));
    }

    @Test
    public void basicWithImages_ImagesSafe() {
        Safelist basicWithImages = Safelist.basicWithImages();
        assertTrue(basicWithImages.isSafeAttribute("img", null, null));
    }

    @Test
    public void relaxed_RelaxedTagsSafe() {
        Safelist relaxed = Safelist.relaxed();
        assertTrue(relaxed.isSafeTag("strong"));
        assertTrue(relaxed.isSafeTag("em"));
    }

    @Test
    public void copy_CopyingSafelist() {
        Safelist original = Safelist.basic();
        Safelist copy = new Safelist(original);
        assertEquals(original, copy);
    }

    @Test
    public void addTags_SafeTagsAdded() {
        Safelist safelist = Safelist.relaxed();
        Set<String> tagsToAdd = new HashSet<>(Arrays.asList("script", "iframe"));
        Safelist updatedSafelist = safelist.addTags(tagsToAdd.toArray(new String[0]));
        assertTrue(updatedSafelist.isSafeTag("script"));
        assertTrue(updatedSafelist.isSafeTag("iframe"));
    }

    @Test
    public void removeTags_SafeTagsRemoved() {
        Safelist safelist = Safelist.relaxed();
        Set<String> tagsToRemove = new HashSet<>(Arrays.asList("strong", "em"));
        Safelist updatedSafelist = safelist.removeTags(tagsToRemove.toArray(new String[0]));
        assertFalse(updatedSafelist.isSafeTag("strong"));
        assertFalse(updatedSafelist.isSafeTag("em"));
    }

    @Test
    public void preserveRelativeLinks_PreserveLinks() {
        Safelist safelist = Safelist.relaxed();
        boolean preserve = true;
        Safelist updatedSafelist = safelist.preserveRelativeLinks(preserve);
        assertTrue(updatedSafelist.preserveRelativeLinks());
    }

    @Test
    public void addProtocols_SafeProtocolsAdded() {
        Safelist safelist = Safelist.relaxed();
        String protocolToAdd = "https";
        Set<String> protocolsToAdd = new HashSet<>(Arrays.asList(protocolToAdd));
        Safelist updatedSafelist = safelist.addProtocols("img", "src", protocolsToAdd.toArray(new String[0]));
        assertTrue(updatedSafelist.getEnforcedAttributes("img").containsKey("src"));
    }

    @Test
    public void removeProtocols_SafeProtocolsRemoved() {
        Safelist safelist = Safelist.relaxed();
        Set<String> protocolsToRemove = new HashSet<>(Arrays.asList("http", "ftp"));
        Safelist updatedSafelist = safelist.removeProtocols("img", "src", protocolsToRemove.toArray(new String[0]));
        assertFalse(updatedSafelist.getEnforcedAttributes("img").containsKey("src"));
    }
}
